// Des: Tests for notify: plain line, channel order, alerts file
// Flo: strings > clean; tmp stat dir > send with file channel > read back
// I/O: text > pass or fail (no real toast in tests)
// Run: zig build test
// ===================================================================
const std = @import("std"); const noti = @import("ru-noti-send.zig"); const conf = @import("cf-conf-load.zig"); const file = @import("st-stor-file.zig"); const T = std.testing;
test "plain line has what and what to do" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try T.expectEqualStrings("za: captcha shown. Solve it in the open window.", try noti.plain(aren.allocator(), "captcha shown", "Solve it in the open window.")); }
test "clean removes shell and quote characters and control codes and caps length" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); try T.expectEqualStrings("a b c d e f g h i j k l m", try noti.clean(alo, "a\"b'c`d$e\\f%g&h|i<j>k\nl\x01m")); const big = try alo.alloc(u8, 500); @memset(big, 'x'); try T.expectEqual(@as(usize, 200), (try noti.clean(alo, big)).len); try T.expectEqualStrings("", try noti.clean(alo, "")); }
test "file channel appends lines and keeps the old ones; toast is skipped in tests" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [200]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}/stat", .{tmpz.sub_path}); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); var cfg: conf.Conf = .{}; cfg.noti_chai_orde = &.{ "toast", "file" }; const one = try noti.send(alo, T.io, cfg, dirz, "first alert", 100, false); try T.expect(!one.toast and !one.hubz and one.file); _ = try noti.send(alo, T.io, cfg, dirz, "second alert", 200, false); const path = try std.fs.path.join(alo, &.{ dirz, "alerts.txt" }); const txt = try file.fileRead(alo, T.io, path, 4096); try T.expectEqualStrings("100 first alert\n200 second alert\n", txt); }
test "channels follow the configured list only" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [200]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}/stat", .{tmpz.sub_path}); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); var cfg: conf.Conf = .{}; cfg.noti_chai_orde = &.{"hubz"}; const done = try noti.send(alo, T.io, cfg, dirz, "x", 1, false); try T.expect(done.hubz and !done.file); const path = try std.fs.path.join(alo, &.{ dirz, "alerts.txt" }); try T.expect(!file.fileHas(T.io, path)); cfg.noti_chai_orde = &.{}; const none = try noti.send(alo, T.io, cfg, dirz, "x", 1, false); try T.expect(!none.hubz and !none.file and !none.toast); }
test "alerts file is trimmed instead of growing forever" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [200]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}/stat", .{tmpz.sub_path}); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); var cfg: conf.Conf = .{}; cfg.noti_chai_orde = &.{"file"}; var idx: i64 = 0; while (idx < 1000) : (idx += 1) _ = try noti.send(alo, T.io, cfg, dirz, "a fairly long alert line to fill the file quickly and trim it", idx, false); const path = try std.fs.path.join(alo, &.{ dirz, "alerts.txt" }); const txt = try file.fileRead(alo, T.io, path, 1 << 20); try T.expect(txt.len < 80 * 1024); try T.expect(std.mem.endsWith(u8, txt, "999 a fairly long alert line to fill the file quickly and trim it\n")); }
